static const char *tag_out = "/app/lagpipe/synctab_out/procance.tag";
static const char *guard_out = "/app/lagpipe/synctab_out/offline_guard.ok";

static void clean_outputs(void) {
    remove(types_out);
    remove(tag_out);
    remove(guard_out);
}

static int fail_gen(const char *message) {
    fprintf(stderr, "%s\n", message);
    clean_outputs();
    return 1;
}

static int run_gen(void) {
    source_pick pick;
    FILE *fp;

    clean_outputs();
    if (choose_layout(&pick) != 0) {
        return fail_gen("imprint: layout pick failed");
